// Created: 2026-08-25

/**
 * Ratchet: hook-side `git status` reads must not take the index lock (#3735).
 *
 * `git status` refreshes the index and writes it back, so it acquires
 * `.git/index.lock` exactly like a write. A hook sampling status collides with
 * whatever the session is doing, and the loser gets "Unable to create
 * index.lock: File exists", which names a stale lock and advises deleting it by
 * hand. The real cause is contention that clears by itself, and the advice is
 * actively dangerous on a repository shared by several worktrees and sessions.
 *
 * This is a SOURCE scan rather than a behavioural test on purpose. The defect
 * is "somebody adds a plain status call later", which no unit test of the
 * current call sites can catch, and reproducing real lock contention in a test
 * would be slow and flaky. Scanning the tree is what actually ratchets.
 */

import { describe, it, expect } from 'vitest';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const SRC = join(fileURLToPath(new URL('../../', import.meta.url)));

function walk(dir: string, out: string[] = []): string[] {
  for (const entry of readdirSync(dir)) {
    if (entry === 'node_modules' || entry === '__tests__' || entry === 'dist') continue;
    const p = join(dir, entry);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (p.endsWith('.ts')) out.push(p);
  }
  return out;
}

describe('#3735: hook-side git status reads do not take the index lock', () => {
  it('every `git status` invocation in hook source passes --no-optional-locks', () => {
    const offenders: string[] = [];

    for (const file of walk(SRC)) {
      const text = readFileSync(file, 'utf8');
      const lines = text.split('\n');

      lines.forEach((line, i) => {
        // Match an argv array that reaches the `status` subcommand. Both shapes
        // used in this codebase are covered: a bare `['status', ...]` and one
        // behind location flags such as `['-C', dir, 'status', ...]`.
        if (!/\[[^\]]*'status'/.test(line)) return;
        if (!/execFileSync\(\s*'git'|'git',\s*\[/.test(line)) return;
        if (line.includes('--no-optional-locks')) return;
        offenders.push(`${relative(SRC, file)}:${i + 1}  ${line.trim()}`);
      });
    }

    expect(
      offenders,
      `These git status calls take .git/index.lock and will break concurrent ` +
        `sessions. Add '--no-optional-locks' as the first argv element:\n` +
        offenders.join('\n'),
    ).toEqual([]);
  });

  // Control: the scanner must be able to fail, otherwise the assertion above is
  // decoration. A synthetic offending line is detected by the same regexes.
  it('the scan can actually fail (positive control)', () => {
    const offending = `    const s = execFileSync('git', ['status', '--porcelain'], {`;
    const clean = `    const s = execFileSync('git', ['--no-optional-locks', 'status', '--porcelain'], {`;

    const looksLikeStatusCall = (line: string) =>
      /\[[^\]]*'status'/.test(line) &&
      /execFileSync\(\s*'git'|'git',\s*\[/.test(line) &&
      !line.includes('--no-optional-locks');

    expect(looksLikeStatusCall(offending)).toBe(true);
    expect(looksLikeStatusCall(clean)).toBe(false);
  });
});
